/* dispatch_rt.c -- run-time side of the dispatch table (runtime-abi 6): miss hook, exact lookup,
 * resume-point lookup. The tables themselves are generated by tools/link/gen_link.py. */
#include <fcntl.h>
#include <mach/mach.h>
#include <mach/mach_vm.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "sg_image.h"

#ifndef SG_REPO_ROOT
#define SG_REPO_ROOT "."
#endif

unsigned long sg_miss_count;

const sg_dispatch_entry *sg_dispatch_find(uint32_t a) {
    uint32_t o = a - SG_TEXT_START, b, i, e;
    if (o >= SG_TEXT_END - SG_TEXT_START) return NULL;
    b = o >> 4;
    for (i = sg_dispatch_bucket[b], e = sg_dispatch_bucket[b + 1]; i < e; i++)
        if (sg_dispatch_entries[i].guest == a) return &sg_dispatch_entries[i];
    return NULL;
}

uint32_t sg_resume_owner(uint32_t r) {
    uint32_t lo = 0, hi = sg_resume_point_count;
    while (lo < hi) {
        uint32_t m = (lo + hi) / 2;
        if (sg_resume_points[m].resume < r) lo = m + 1;
        else hi = m;
    }
    return lo < sg_resume_point_count && sg_resume_points[lo].resume == r ? sg_resume_points[lo].func : 0;
}

/* Reads guest memory without faulting (the miss hook may run with a corrupt frame chain). */
static int peek32(const uint8_t *mem, uint32_t a, uint32_t *v) {
    mach_vm_size_t got = 0;
    if (a < SG_NULL_GUARD_END || a > 0xfffffffcu) return 0;
    return mach_vm_read_overwrite(mach_task_self(), (mach_vm_address_t)(uintptr_t)(mem + a), 4,
                                  (mach_vm_address_t)(uintptr_t)v, &got) == KERN_SUCCESS && got == 4;
}

/* Function containing `a` (nearest dispatch entry at or below it), for readable reports. */
static uint32_t owner_of(uint32_t a) {
    uint32_t lo = 0, hi = sg_dispatch_count;
    if (a < SG_TEXT_START || a >= SG_TEXT_END || !hi) return 0;
    while (lo < hi) {
        uint32_t m = (lo + hi) / 2;
        if (sg_dispatch_entries[m].guest <= a) lo = m + 1;
        else hi = m;
    }
    return lo ? sg_dispatch_entries[lo - 1].guest : 0;
}

static void miss_continue_stub(sg_ctx *ctx, uint8_t *mem) { ctx->eax = 0; SG_RET(0); }

sg_func *sg_image_miss_hook(sg_ctx *ctx, uint8_t *mem, uint32_t guest) {
    uint32_t ra = 0, ebp = ctx->ebp, owner = sg_resume_owner(guest);
    const char *path = getenv("SPORE_MISS_LOG");
    const char *pol = getenv("SPORE_MISS");
    char line[256];
    int i, fd;
    __atomic_fetch_add(&sg_miss_count, 1, __ATOMIC_RELAXED);
    peek32(mem, ctx->esp, &ra);
    fprintf(stderr, "spore: dispatch miss: guest 0x%08x", guest);
    if (guest >= SG_TEXT_START && guest < SG_TEXT_END)
        fprintf(stderr, " (inside .text, nearest entry below 0x%08x)", owner_of(guest));
    else if (guest - SG_THUNK_BASE < SG_THUNK_LIMIT - SG_THUNK_BASE)
        fprintf(stderr, " (thunk slot %u is empty)", (guest - SG_THUNK_BASE) / SG_THUNK_SLOT);
    else
        fprintf(stderr, " (not code: outside .text and the thunk region)");
    if (owner) fprintf(stderr, "\n  it is an EH resume point of 0x%08x: a computed jump there is a bug (abi 6.1)", owner);
    fprintf(stderr, "\n  caller: [esp]=0x%08x (return address of an indirect call; for an indirect jmp, the"
                    " enclosing function's) in 0x%08x; last ret eip=0x%08x esp=0x%08x ebp=0x%08x\n",
            ra, owner_of(ra), ctx->eip, ctx->esp, ctx->ebp);
    fprintf(stderr, "  ebp chain:");
    for (i = 0; i < 16 && ebp; i++) {
        uint32_t next, ret;
        if (!peek32(mem, ebp, &next) || !peek32(mem, ebp + 4u, &ret)) break;
        fprintf(stderr, " 0x%08x", ret);
        if (next <= ebp) break;
        ebp = next;
    }
    fprintf(stderr, "\n");
    snprintf(line, sizeof line, "%08x caller=%08x eip=%08x\n", guest, ra, ctx->eip);
    if (!path) path = SG_REPO_ROOT "/build/sporenative/misses.txt";
    fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd >= 0) { (void)!write(fd, line, strlen(line)); close(fd); }
    if (pol && !strcmp(pol, "continue")) {
        fprintf(stderr, "  SPORE_MISS=continue: returning 0 (cdecl) to the caller\n");
        return miss_continue_stub;
    }
    abort();
}

__attribute__((weak)) sg_miss_hook_fn sg_miss_hook = sg_image_miss_hook;
